CREATE TABLE integration_connections(id TEXT PRIMARY KEY CHECK(id='athledata'),user_id TEXT NOT NULL REFERENCES users(id),status TEXT NOT NULL,account_key TEXT,credentials_enc TEXT,credential_version INTEGER NOT NULL DEFAULT 0,metadata_json TEXT NOT NULL DEFAULT '{}',tools_json TEXT NOT NULL DEFAULT '[]',last_success_at INTEGER,last_error_code TEXT,updated_at INTEGER NOT NULL);
CREATE TABLE oauth_transactions(id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES auth_sessions(id) ON DELETE CASCADE,state_hash TEXT NOT NULL UNIQUE,pkce_enc TEXT NOT NULL,metadata_json TEXT NOT NULL,scopes_json TEXT NOT NULL,expires_at INTEGER NOT NULL,consumed_at INTEGER);
CREATE TABLE integration_leases(integration_id TEXT PRIMARY KEY REFERENCES integration_connections(id),holder TEXT NOT NULL,lease_until INTEGER NOT NULL);
CREATE TABLE external_workout_refs(id TEXT PRIMARY KEY,integration_id TEXT NOT NULL REFERENCES integration_connections(id),account_key TEXT NOT NULL,workout_id TEXT NOT NULL REFERENCES workouts(id),external_workout_id TEXT NOT NULL,planned_revision INTEGER NOT NULL,generation INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN ('active','superseded','deleted')),created_at INTEGER NOT NULL,FOREIGN KEY(workout_id,planned_revision) REFERENCES workout_revisions(workout_id,revision),UNIQUE(integration_id,account_key,workout_id,generation));
CREATE UNIQUE INDEX external_active ON external_workout_refs(integration_id,account_key,workout_id) WHERE state='active';
CREATE INDEX external_lookup ON external_workout_refs(account_key,external_workout_id);
CREATE UNIQUE INDEX external_owned_identity ON external_workout_refs(account_key,external_workout_id) WHERE state='active';
CREATE TABLE sync_operations(id TEXT PRIMARY KEY,integration_id TEXT NOT NULL REFERENCES integration_connections(id),account_key TEXT NOT NULL,workout_id TEXT REFERENCES workouts(id),target_revision INTEGER,kind TEXT NOT NULL CHECK(kind IN ('create','update','delete','import')),state TEXT NOT NULL CHECK(state IN ('queued','in_flight','succeeded','failed','ambiguous','cancelled','blocked_auth','blocked_capability')),idempotency_key TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,payload_json TEXT NOT NULL,dispatched_at INTEGER,completed_at INTEGER,last_error_code TEXT,created_at INTEGER NOT NULL,FOREIGN KEY(workout_id,target_revision) REFERENCES workout_revisions(workout_id,revision));
CREATE INDEX sync_pending ON sync_operations(state,created_at);
ALTER TABLE sync_operations ADD COLUMN result_json TEXT;
CREATE TABLE sync_history(id TEXT PRIMARY KEY,operation_id TEXT NOT NULL REFERENCES sync_operations(id),state TEXT NOT NULL,error_code TEXT,created_at INTEGER NOT NULL);
CREATE TABLE completed_activities(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),account_key TEXT NOT NULL,external_activity_id TEXT NOT NULL,origin_namespace TEXT NOT NULL,sport TEXT NOT NULL,start_at INTEGER NOT NULL,local_date TEXT NOT NULL,elapsed_s REAL,distance_m REAL,avg_hr_bpm REAL,avg_power_w REAL,planned_external_id TEXT,details_json TEXT NOT NULL,payload_hash TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,fetched_at INTEGER NOT NULL,UNIQUE(account_key,origin_namespace,external_activity_id));
CREATE INDEX activity_dates ON completed_activities(user_id,local_date,sport);
CREATE TABLE activity_sources(id TEXT PRIMARY KEY,activity_id TEXT NOT NULL REFERENCES completed_activities(id),integration_id TEXT NOT NULL REFERENCES integration_connections(id),source_id TEXT NOT NULL,account_key TEXT NOT NULL,UNIQUE(integration_id,account_key,source_id));
CREATE TABLE activity_revisions(id TEXT PRIMARY KEY,activity_id TEXT NOT NULL REFERENCES completed_activities(id),snapshot_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE workout_activity_links(id TEXT PRIMARY KEY,workout_id TEXT NOT NULL REFERENCES workouts(id),activity_id TEXT NOT NULL REFERENCES completed_activities(id),planned_revision INTEGER NOT NULL,method TEXT NOT NULL,confidence REAL,created_at INTEGER NOT NULL,unlinked_at INTEGER,FOREIGN KEY(workout_id,planned_revision) REFERENCES workout_revisions(workout_id,revision));
CREATE UNIQUE INDEX active_activity_link ON workout_activity_links(activity_id) WHERE unlinked_at IS NULL;
CREATE UNIQUE INDEX active_plan_link ON workout_activity_links(workout_id) WHERE unlinked_at IS NULL;
CREATE TABLE import_cursors(integration_id TEXT PRIMARY KEY REFERENCES integration_connections(id),cursor_json TEXT,last_success_at INTEGER);
